<?php session_start(); if(!isset($_SESSION['admin_logged_in'])) header("Location: index.php"); require_once '../config/database.php'; 
$topProducts=$pdo->query("SELECT p.name, SUM(oi.quantity) as total_sold, SUM(oi.quantity*oi.price) as revenue FROM order_items oi LEFT JOIN products p ON oi.product_id=p.id GROUP BY oi.product_id ORDER BY total_sold DESC LIMIT 10");
$topClients=$pdo->query("SELECT c.name, COUNT(o.id) as order_count, SUM(o.total_amount) as total_spent FROM clients c LEFT JOIN orders o ON c.id=o.client_id GROUP BY c.id ORDER BY total_spent DESC LIMIT 10");
?>
