<html><head><title>Reports</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:'Inter',sans-serif;background:#0a0a0a;color:#e8e0d8;}.sidebar{position:fixed;left:0;top:0;width:260px;height:100%;background:#111;padding:2rem 1rem;}.sidebar a{display:block;padding:0.8rem 1rem;color:#e8e0d8;text-decoration:none;margin:0.5rem 0;border-radius:8px;}.sidebar a:hover,.sidebar a.active{background:#d4af7a;color:#0a0a0a;}.content{margin-left:260px;padding:2rem;}.report-box{background:rgba(255,255,255,0.03);border-radius:12px;padding:1.5rem;margin-bottom:2rem;}table{width:100%;}th,td{padding:0.8rem;text-align:left;border-bottom:1px solid #222;}h2{color:#d4af7a;margin-bottom:1rem;}</style></head>
