<div class="content"><h1>Reports</h1><div class="report-box"><h2>🏆 Top 10 Best Selling Products</h2><table><thead><tr><th>Product</th><th>Units Sold</th><th>Revenue</th></tr></thead><tbody><?php while($p=$topProducts->fetch()): ?><tr><td><?php echo htmlspecialchars($p['name']); ?></td><td><?php echo $p['total_sold']; ?></td><td>$<?php echo number_format($p['revenue'],2); ?></td></tr><?php endwhile; ?></tbody></table></div><div class="report-box"><h2>👑 Top 10 Clients (Highest Spending)</h2><table><thead><tr><th>Client Name</th><th>Orders</th><th>Total Spent</th></tr></thead><tbody><?php while($c=$topClients->fetch()): ?><tr><td><?php echo htmlspecialchars($c['name']); ?></td><td><?php echo $c['order_count']; ?></td><td>$<?php echo number_format($c['total_spent'],2); ?></td></tr><?php endwhile; ?></tbody></table></div></div></body></html>